def dice_loss(logits, target, eps=1.0):
    probs = logits.softmax(1)
    t = F.one_hot(target, logits.shape[1]).permute(0, 3, 1, 2).float()
    inter = (probs * t).sum(dim=(0, 2, 3))
    denom = probs.sum(dim=(0, 2, 3)) + t.sum(dim=(0, 2, 3))
    return 1 - ((2 * inter + eps) / (denom + eps)).mean()

def seg_loss(logits, target, w=0.5):
    # CE gives per-pixel gradient everywhere; Dice directly optimizes overlap and is
    # insensitive to class imbalance (a 1%-foreground mask kills plain CE).
    return (1 - w) * F.cross_entropy(logits, target) + w * dice_loss(logits, target)

from collections import Counter

def get_pairs(tokens):
    return Counter(zip(tokens, tokens[1:]))

def train_bpe(text, num_merges):
    tokens = list(text)                    # start from characters
    merges = []
    for _ in range(num_merges):
        pairs = get_pairs(tokens)
        if not pairs: break
        best = max(pairs, key=pairs.get)   # most frequent adjacent pair
        merges.append(best)
        # merge every occurrence of `best` into a single token
        merged, i = [], 0
        while i < len(tokens):
            if i < len(tokens)-1 and (tokens[i], tokens[i+1]) == best:
                merged.append(tokens[i] + tokens[i+1]); i += 2
            else:
                merged.append(tokens[i]); i += 1
        tokens = merged
    return merges, tokens

